/* ACNL save data (garden_plus.dat) - generated by tools/decomp/export_ghidra.py.
   Load in Ghidra with File > Parse C Source (pack 1 is required). */

typedef unsigned char u8;
typedef unsigned short u16;
typedef unsigned int u32;
typedef unsigned long long u64;
typedef signed char s8;
typedef short s16;
typedef int s32;
typedef long long s64;
typedef unsigned short char16;
typedef u64 SvEncValue;
typedef s64 SvTime;

#pragma pack(push, 1)

typedef struct SvFgName {
    u16 id; /* SvFgName::Name, 0x7FFE = empty */
    u16 flags;
} SvFgName;

/* ---- dSvCommon.h ---- */
// Basic value types of the save data (dates, encrypted values, time).
//
// Offsets in /* */ are relative to the struct and verified by the ASSERT_SIZE checks.

// Values that the game stores obfuscated (bells, medals, ...): see SvEncValue tools.

// Nanoseconds since 2000-01-01 00:00:00 (not since 1970).

typedef struct SvDate {
    /* 0x0000 */ u16 year;
    /* 0x0002 */ u8 month;
    /* 0x0003 */ u8 day;
} SvDate;

typedef struct SvDateTime {
    /* 0x0000 */ u16 year;
    /* 0x0002 */ u16 unk_0x2; // Maybe padding
    /* 0x0004 */ u8 month;
    /* 0x0005 */ u8 day;
    /* 0x0006 */ u8 unk_0x6; // some sort of flag probably
    /* 0x0007 */ u8 hour;
    /* 0x0008 */ u8 minute;
    /* 0x0009 */ u8 second;
    /* 0x000A */ u16 millisecond;
} SvDateTime;

