/* ---- dSvPersonalId.h ---- */
// Identities of towns and players as stored in the save data.
//
// Offsets in /* */ are relative to the struct and verified by the ASSERT_SIZE checks.

typedef struct SvTownId {
    /* 0x0000 */ u16 tid; // Default is 0
    /* 0x0002 */ char16 dataTownName[9]; // Default is 0
    /* 0x0014 */ u8 unk_0x14; // Default is 0xA
    /* 0x0015 */ u8 unk_0x15;
} SvTownId;

typedef struct SvPlayerId {
    /* 0x0000 */ u16 pid;
    /* 0x0002 */ char16 playerName[9];
    /* 0x0014 */ u8 gender;
    /* 0x0015 */ u8 pad_0x15;
} SvPlayerId;

typedef struct SvPersonalId {
    /* 0x0000 */ SvPlayerId playerData;
    /* 0x0016 */ SvTownId townData;
    /* 0x002C */ u8 tpcCountry;
    /* 0x002D */ u8 tpcCounty;
} SvPersonalId;

/* ---- dSvMyDesign.h ---- */
// Custom designs ("My Design" patterns).
//
// Offsets in /* */ are relative to the struct and verified by the ASSERT_SIZE checks.

typedef struct SvMyDesign {
    /* 0x0000 */ char16 title[0x15];
    /* 0x002A */ SvPersonalId creatorData;
    /* 0x0058 */ u8 palette[0xF];
    /* 0x0067 */ u8 unk_0x67; // research name: UnusedChecksum / changing seems to have no effect / Default: 1, Set at 0x1B4F74 EUR 1.5
    /* 0x0068 */ u8 tenConstant; // seems to always be 0x0A
    /* 0x0069 */ u8 patternType;
    /* 0x006A */ u16 pad_0x6A; // Zero Padding; Always 0x0000
    /* 0x006C */ u8 patternData1[0x200]; // mandatory
    /* 0x026C */ u8 patternData2[0x200]; // optional
    /* 0x046C */ u8 patternData3[0x200]; // optional
    /* 0x066C */ u8 patternData4[0x200]; // optional
    /* 0x086C */ u32 pad_0x86C; // Zero Padding; Optional*/
} SvMyDesign;

/* ---- dSvMail.h ---- */
// Letters (mail) and mail related flags.
//
// Offsets in /* */ are relative to the struct and verified by the ASSERT_SIZE checks.

typedef struct SvMail {
    /* 0x0000 */ SvPersonalId receiver;
    /* 0x002E */ u16 pad_0x2E;
    /* 0x0030 */ u16 receiverId;
    /* 0x0032 */ u8 pad_0x32[0x32];
    /* 0x0064 */ u16 unk_0x64; // Some form of ID?
    /* 0x0066 */ u16 pad_0x66;
    /* 0x0068 */ char16 header[0x20]; // Max amount is 32 UTF-16 characters
    /* 0x00A8 */ u16 pad_0xA8;
    /* 0x00AA */ char16 body[0xC0]; // Max amount is 192 UTF-16 characters
    /* 0x022A */ u16 pad_0x22A;
    /* 0x022C */ char16 signature[0x20]; // Max amount is 32 UTF-16 characters
    /* 0x026C */ u16 pad_0x26C;
    /* 0x026E */ u8 receiverNameIndent;
    /* 0x026F */ u8 paperId;
    /* 0x0270 */ u8 letterFlag; // 9 closed
    /* 0x0271 */ u8 stringIdOfSender;
    /* 0x0272 */ u8 letterType; // 0x88 time capsule
    /* 0x0273 */ u8 unk_0x273;
    /* 0x0274 */ SvFgName attachedItem;
    /* 0x0278 */ u64 unk_0x278;
} SvMail;

